class Originator {
  private state: string;
  setState(s: string) { this.state = s }
  createSnapshot() { return new Snapshot(this.state) }
  restore(snapshot: Snapshot) { this.state = snapshot.getState() }
}

class Snapshot {
  constructor(private state: string) {}
  getState() { return this.state }
}

class Caretaker {
  private history: Snapshot[] = []
  save(s: Snapshot) { this.history.push(s) }
  undo() { return this.history.pop() }
}

class Editor {
  private doc: string = ''
  private history: string[] = []
  type(text: string) { this.doc += text }
  snapshot() { this.history.push(this.doc) }
  undo() { this.doc = this.history.pop() || '' }
}

